/**
 * The Study backdrop, as a base64 data URL rather than a binary asset file.
 *
 * Why: this repo is pushed to GitHub via an API path that only reliably
 * transports UTF-8 text (binary file uploads through it get corrupted --
 * verified during setup: a raw .jpg came back mangled both as a plain
 * base64 blob and as a latin1-mapped string). Storing the image as base64
 * text sidesteps that entirely, and since the production build already
 * inlines all assets as base64 into one HTML file (vite-plugin-singlefile),
 * this has zero runtime cost or behavior difference versus importing a
 * .jpg asset directly -- it's simply base64-encoded ahead of time instead
 * of at build time.
 *
 * To regenerate this image (different time of day, composition, etc.):
 * see HANDOFF.md for the original AI generation prompt, produce a new
 * study.jpg locally, then rebuild this module from it (see repo history
 * for the exact one-liner, or just base64-encode the file and wrap it in
 * an `export const studyImageDataUrl = "data:image/jpeg;base64,...";`).
 */

export const studyImageDataUrl =
  'data:image/jpeg;base64,';
